import {SHIFT_MODULES} from './shift-hardware.js';
import {EXTRA_SENSOR_MODULES} from './extra-sensor-hardware.js';
import {SPI_GPIO_MODULES} from './spi-gpio-hardware.js';
import {TFT_MODULES} from './tft-hardware.js';
import {tftDisplay,updateTFT} from './tft-ui.js';
import {ACTUATOR_MODULES} from './actuator-hardware.js';
import {actuatorDisplay,updateActuators} from './actuator-ui.js';
import {LOADCELL_MODULES} from './loadcell-hardware.js';
import {DIGITAL_MODULES} from './digital-hardware.js';
import {digitalDisplay,updateDigital} from './digital-ui.js';
import {PULSE_MODULES} from './pulse-hardware.js';
import {LAB_MODULES} from './lab-hardware.js';
import {BASIC_MODULES} from './basic-hardware.js';
import {readInstrument,instrumentText} from './instruments.js';
import {SENSOR_MODULES} from './sensor-hardware.js';
import {CATALOG} from './core.js';import {EXPANDED_MODULES} from './expanded-hardware.js';import {PART_FIELDS} from './part-parameters.js';
const $=id=>document.getElementById(id),hex=b=>b.toString(16).toUpperCase().padStart(2,'0');
export function expandedInspector(c){const fields=(PART_FIELDS[c.type]||[]).filter(f=>f.key!=='keyMask').map(f=>{const scale=f.scale||1;if(f.options)return `<div class="property"><label for="part-${f.key}">${f.label}</label><select data-part-parameter="${f.key}" id="part-${f.key}">${f.options.map(([v,label])=>`<option value="${v}" ${(c.params[f.key]??f.value)===v?'selected':''}>${label}</option>`).join('')}</select></div>`;if(f.key==='address')return `<div class="property"><label for="part-address">I²C adres</label><select id="part-address" data-part-parameter="address">${Array.from({length:8},(_,i)=>`<option value="${32+i}" ${(c.params.address??39)===32+i?'selected':''}>0x${hex(32+i)}</option>`).join('')}</select></div>`;return `<div class="property"><label for="part-${f.key}">${f.label}</label><input data-part-parameter="${f.key}" id="part-${f.key}" type="number" min="${f.min*scale}" max="${f.max*scale}" step="${f.step}" value="${(c.params[f.key]??f.value)*scale}"></div>`;}).join('');const module=SHIFT_MODULES[c.type]||EXTRA_SENSOR_MODULES[c.type]||SPI_GPIO_MODULES[c.type]||TFT_MODULES[c.type]||ACTUATOR_MODULES[c.type]||LOADCELL_MODULES[c.type]||DIGITAL_MODULES[c.type]||EXPANDED_MODULES[c.type]||SENSOR_MODULES[c.type]||LAB_MODULES[c.type]||BASIC_MODULES[c.type]||PULSE_MODULES[c.type];return fields+(module||['opamp','diode','zener'].includes(c.type)?'<div class="property"><label>Model</label><strong id="expanded-state">—</strong></div><div id="expanded-values" class="device-values"></div>':'')+(['capacitor','inductor'].includes(c.type)?'<div class="property"><label>Depolanan</label><strong id="reactive-state">—</strong></div>':'');}
export function bindExpandedInspector(c,edit,toast){for(const node of document.querySelectorAll('[data-part-parameter]'))node.onchange=()=>{const f=PART_FIELDS[c.type].find(f=>f.key===node.dataset.partParameter);if(f.options){const option=f.options.find(o=>String(o[0])===node.value);if(option)edit(()=>c.params[f.key]=option[0]);return;}const n=node.value.trim()===''?NaN:Number(node.value)/(f.scale||1);if(!Number.isFinite(n)||n<f.min||n>f.max||(f.step===1&&f.key!=='lux'&&!Number.isInteger(n))){node.value=(c.params[f.key]??f.value)*(f.scale||1);toast(f.label+': '+f.min*(f.scale||1)+'–'+f.max*(f.scale||1));return;}edit(()=>c.params[f.key]=n);};}
export function expandedDisplay(c){if(TFT_MODULES[c.type])return tftDisplay(c);if(ACTUATOR_MODULES[c.type])return actuatorDisplay(c);if(DIGITAL_MODULES[c.type])return digitalDisplay(c);if(c.type==='servo'){const d=CATALOG.servo,r=PULSE_MODULES.servo.pivot;return `<g transform="translate(${r.x*d.scale} ${r.y*d.scale})"><g data-servo-arm="${c.id}"><path d="M-3 -5h42v10H-3Z" fill="#e3e7e9" stroke="#99a9b3" stroke-width="1"/><circle r="3" fill="#778a93"/><circle cx="32" r="2" fill="#263a4a"/></g></g>`;}if(LAB_MODULES[c.type]){const d=CATALOG[c.type],r=LAB_MODULES[c.type].display;return `<svg x="${r.x*d.scale}" y="${r.y*d.scale}" width="${r.width*d.scale}" height="${r.height*d.scale}" viewBox="0 0 ${r.width} ${r.height}" pointer-events="none"><rect width="${r.width}" height="${r.height}" fill="#13222a"/><text data-instrument="${c.id}" x="${r.width-8}" y="29" text-anchor="end" fill="#78f7cc" font-family="Consolas,monospace" font-size="${c.type==='signalgen'?25:19}">OL</text><text data-instrument-mode="${c.id}" x="7" y="41" fill="#8eaeb4" font-size="7"></text></svg>`;}const d=CATALOG[c.type],r=EXPANDED_MODULES[c.type]?.display;if(!r)return '';let body='';if(c.type.startsWith('lcd'))body=`<rect width="${r.width}" height="${r.height}" data-lcd-backlight="${c.id}" fill="#26452b"/>`+Array.from({length:2},(_,row)=>Array.from({length:r.columns},(_,col)=>`<g transform="translate(${5+col*(r.width-10)/r.columns} ${5+row*(r.height-10)/2})"><text data-lcd-char="${c.id}" data-row="${row}" data-col="${col}" x="0" y="${(r.height-10)/2-3}" font-family="Consolas,monospace" font-size="${Math.min(19,(r.width-10)/r.columns*1.5)}" fill="#b6f880"></text><path data-lcd-glyph="${c.id}" data-row="${row}" data-col="${col}" fill="#b6f880"/></g>`).join('')).join('');
else if(c.type==='matrix8')body='<rect width="112" height="112" fill="#0c1018"/>'+Array.from({length:64},(_,i)=>`<circle data-matrix-led="${c.id}" data-row="${i>>3}" data-col="${i&7}" cx="${7+(i&7)*14}" cy="${7+(i>>3)*14}" r="4.3" fill="#381a20"/>`).join('');
else body=`<rect width="248" height="55" fill="#090c12"/>`+Array.from({length:8},(_,digit)=>`<g transform="translate(${3+digit*30} 4)">${['M6 0h13l3 3-4 3H7L3 3Z','M23 4v16l-3 3-3-3V7Z','M23 25v16l-6-3V28l3-3Z','M6 40h12l4 3-3 3H6l-3-3Z','M1 25l5 3v10l-5 3Z','M1 4l5 3v13l-3 3-2-3Z','M6 20h12l3 3-3 3H6l-3-3Z'].map((path,segment)=>`<path data-digit-segment="${c.id}" data-digit="${7-digit}" data-bit="${6-segment}" d="${path}" fill="#351923"/>`).join('')}<circle data-digit-segment="${c.id}" data-digit="${7-digit}" data-bit="7" cx="26" cy="43" r="2" fill="#351923"/></g>`).join('');
return `<svg x="${r.x*d.scale}" y="${r.y*d.scale}" width="${r.width*d.scale}" height="${r.height*d.scale}" viewBox="0 0 ${r.width} ${r.height}" pointer-events="none" aria-label="${c.id} canlı ekran">${body}</svg>`;}
export function updateExpanded(project,snapshot,sim,selected){const packet={...snapshot,...snapshot?.dc?.peripherals};updateTFT(packet);updateDigital(packet);updateActuators(packet);const modules={...packet.dc?.parallelLCD,...packet.i2c?.modules,...packet.spi?.modules,...packet.onewire?.modules,...packet.uartDevices?.modules,...packet.digitalDevices?.modules,...packet.actuatorDevices?.modules,...packet.tftDevices?.modules,...packet.spiGPIO?.modules,...packet.thermocouple?.modules,...packet.shiftDevices?.modules};
// BMP exists on either adapter; select its active interface, never an idle duplicate.
for(const[id,d]of Object.entries(packet.i2c?.modules||{}))if(d.type==='bmp280'&&d.connected)modules[id]=d;
for(const node of document.querySelectorAll('[data-lcd-char]')){const d=modules[node.dataset.lcdChar],code=d?.cells?.[+node.dataset.row]?.[+node.dataset.col]??32;node.textContent=d?.powered&&d.on&&code>=32&&code<=126?String.fromCharCode(code):'';}
for(const node of document.querySelectorAll('[data-lcd-glyph]')){const d=modules[node.dataset.lcdGlyph],code=d?.cells?.[+node.dataset.row]?.[+node.dataset.col]??32;let path='';if(d?.powered&&d.on&&code<16)for(let y=0;y<8;y++)for(let x=0;x<5;x++)if(d.cgram[(code&7)*8+y]&(1<<(4-x)))path+=`M${x*2.4} ${y*2.4}h2v2h-2Z`;node.setAttribute('d',path);}
for(const node of document.querySelectorAll('[data-lcd-backlight]'))node.setAttribute('fill',modules[node.dataset.lcdBacklight]?.powered&&modules[node.dataset.lcdBacklight]?.backlight?'#466d37':'#14211b');
for(const node of document.querySelectorAll('[data-matrix-led],[data-digit-segment]')){const d=modules[node.dataset.matrixLed||node.dataset.digitSegment],bit=node.dataset.bit!==undefined?+node.dataset.bit:7-Number(node.dataset.col),index=node.dataset.digit!==undefined?+node.dataset.digit:+node.dataset.row,on=d?.powered&&((d.frame?.[index]||0)&(1<<bit));node.setAttribute('fill',on?'#ff4652':'#351923');node.setAttribute('opacity',on ? .3+.7*((d.intensity??15)+1)/16:1);}
for(const node of document.querySelectorAll('[data-instrument]')){const c=project.components.find(c=>c.id===node.dataset.instrument);if(c)node.textContent=instrumentText(readInstrument(project,c,sim.dc));}for(const node of document.querySelectorAll('[data-instrument-mode]')){const c=project.components.find(c=>c.id===node.dataset.instrumentMode);if(c)node.textContent=c.type==='signalgen'?(c.params.wave??'square').toUpperCase()+' · '+(c.params.frequency??10)+' Hz · 50 Ω':c.type==='ohmmeter'?'PASSIVE · 1 V TEST':(c.params.mode??'voltage').toUpperCase();}for(const node of document.querySelectorAll('[data-servo-arm]')){const s=packet.pulseDevices?.[node.dataset.servoArm];node.setAttribute('transform','rotate('+((s?.angle??90)-90)+')');}const c=project.components.find(c=>c.id===selected?.id);if(!c)return;if(PULSE_MODULES[c.type]){const d=packet.pulseDevices?.[c.id];if($('expanded-state'))$('expanded-state').textContent=d?.powered?'Besleme OK':'Besleme yok / başlatın';if($('expanded-values'))$('expanded-values').textContent=c.type==='servo'?(d?.valid?d.angle.toFixed(1)+'° · '+d.pulse.toFixed(1)+' µs · '+(d.period/1000).toFixed(2)+' ms':'Geçerli PWM bekleniyor')+' · kalibre model':(d?.captures??0)+' TRIG · '+(d?.echo?'ECHO HIGH':d?.busy?'BURST / bekleme':'IDLE');return;}if(LAB_MODULES[c.type]){if($('expanded-state'))$('expanded-state').textContent=instrumentText(readInstrument(project,c,sim.dc));if($('expanded-values'))$('expanded-values').textContent=c.type==='signalgen'?'50 Ω · sinüs/üçgen 64 örnek, ≥10 µs':c.type==='multimeter'?c.params.mode==='current'?'A→COM · 0.1 Ω · seri bağlantı':'V→COM · '+(c.params.mode==='resistance'?'Pasif ağ / kaynakları ayırın':'10 MΩ'):'Pasif ağ · LIVE=enerjili / ACTIVE=model dışı';return;}if(BASIC_MODULES[c.type]){const n=sim.dc.netlist.net,vcc=sim.dc.voltages.get(n(c.id+':VCC')),gnd=sim.dc.voltages.get(n(c.id+':GND')),powered=Number.isFinite(vcc)&&Number.isFinite(gnd)&&vcc-gnd>=BASIC_MODULES[c.type].specs.supplyMin&&vcc-gnd<=BASIC_MODULES[c.type].specs.supplyMax;if($('expanded-state'))$('expanded-state').textContent=powered?'Besleme OK':'Besleme yok / aralık dışı';if($('expanded-values'))$('expanded-values').textContent=BASIC_MODULES[c.type].pins.filter(p=>!['VCC','GND'].includes(p.id)).map(p=>{const v=sim.dc.voltages.get(n(c.id+':'+p.id));return p.id+' '+(Number.isFinite(v)&&Number.isFinite(gnd)?(v-gnd).toFixed(3)+' V':'Hi-Z');}).join(' · ')+(c.type==='pir'&&packet.basicDevices?.[c.id]?' · '+packet.basicDevices[c.id].phase.toUpperCase():'');return;}const d=modules[c.id],value=(n,unit)=>Number.isFinite(n)?n.toFixed(3)+' '+unit:'Hi-Z';
if($('expanded-state'))$('expanded-state').textContent=d?(d.powered?d.connected?'Bağlı':'Besleme OK':'Besleme yok')+(d.conflict?' · UART çakışması':d.resetAsserted?' · RESET':d.overvoltage?' · IO > VCC':d.format===false?' · 9600 8N1 gerekli':''):['diode','zener'].includes(c.type)?'DC · '+(sim.dc.deviceResults.get(c.id)?.state||'Hi-Z'):c.type==='l298n'?'Çift H-köprü · DC':c.type==='loadcell'?'Wheatstone · pasif':c.type==='opamp'?'Opamp · DC':c.type==='ldr'?'Direnç':c.type==='tmp36'?(sim.dc.sensorResults?.get(c.id)?.powered?'Analog · bağlı':'Besleme yok'):'—';
if($('expanded-values')){let text='';if(d){if(c.type==='hc595'||c.type==='hc165')text='SHIFT '+hex(d.shift)+(c.type==='hc595'?' · LATCH '+hex(d.latch)+' · '+(d.enabled?'OUT':'Hi-Z'):'')+' · '+d.clocks+' CLK · '+d.loads+' LOAD';else if(c.type.startsWith('tft'))text=d.writes+' pixel · '+d.bytes+' SPI byte · RGB'+(d.format===5?'565':'666 / kapsam dışı')+' · '+d.errors+' hata';else if(c.type==='ws2812')text=d.frames+' GRB frame · '+d.errors+' timing error';else if(c.type==='stepper28byj')text=d.steps+' half-step · '+d.angle.toFixed(2)+'° · '+(d.currents||[]).map(a=>(a*1000).toFixed(1)).join('/')+' mA';else if(c.type.startsWith('dht'))text=(d.frames??0)+' frame · '+(d.busy?'DATA':'IDLE')+' · harici 5.1 kΩ';else if(c.type==='hx711')text=(d.sleep?'POWER DOWN':d.ready?'READY':'CONV')+' · '+d.channel+'/'+d.gain+' · '+(d.inputValid?d.code:'giriş Hi-Z / ortak mod')+' · '+d.samples+' sample';else if(c.type==='ky040')text=d.position+' detent · '+d.phase.toString(2).padStart(2,'0');else if(c.type.startsWith('lcd'))text=(d.interface==='parallel'?'4/8-bit · '+d.writes+' yazma':'0x'+hex(d.address))+' · '+(d.on?'DISPLAY ON':'DISPLAY OFF');else if(c.type==='sht31')text=d.temperature.toFixed(2)+' °C · '+d.humidity.toFixed(2)+' %RH'+(d.measuring?' · CONV':'')+(d.heater?' · HEATER':'')+(d.stretching?' · STRETCH':'')+(d.supported===false?' · Komut desteklenmiyor':'');else if(c.type==='bh1750')text=d.lux.toFixed(1)+' lux · MT '+d.mtreg+(d.measuring?' · CONV':'')+(d.supported===false?' · Mod desteklenmiyor':'');else if(c.type==='mpu6050')text=(d.sleeping?'SLEEP':'±'+d.accelRange+'g / ±'+d.gyroRange+'°/s')+' · '+Math.round(d.sampleHz)+' Hz · FIFO '+d.fifoBytes+(d.interrupt?' · INT':'')+(d.unsupported?' · Mod kapsam dışı':'');else if(c.type==='ina219')text=d.busVoltage.toFixed(3)+' V · '+(d.shuntVoltage*1000).toFixed(2)+' mV · RAW I:'+d.currentCode+' P:'+d.powerCode+(d.overflow?' · OVF':'')+(d.inputValid?'':' · VIN aralık dışı');else if(c.type==='max6675')text=(d.open?'OPEN':d.temperature.toFixed(2)+' °C')+' · '+d.samples+' sample'+(d.converting?' · CONV':'');else if(c.type==='mcp23s17')text='GPIO '+d.gpio.map(hex).join('/')+' · DIR '+d.iodir.map(hex).join('/')+' · INT '+d.interrupt.map(hex).join('/')+' · '+d.bytes+' SPI byte';else if(c.type==='mcp23017')text='GPIO A:'+hex(d.gpio[0])+' B:'+hex(d.gpio[1])+' · DIR '+d.iodir.map(hex).join('/')+' · INT '+d.interrupt.map(hex).join('/')+(d.unknown.some(Boolean)?' · Hi-Z '+d.unknown.map(hex).join('/'):'')+' · A7/B7 OUT';else if(c.type==='bmp280')text=d.temperature.toFixed(1)+' °C · '+d.pressure.toFixed(2)+' hPa';else if(c.type==='mcp3008')text='CH'+d.channel+' = '+(d.code??'INVALID')+' · '+d.samples+' sample'+(d.timingError?' · '+d.timingError:!d.sourceSupported?' · source model':Number.isFinite(d.sourceOhms)?' · '+(d.sourceOhms/1000).toFixed(1)+' kΩ':'');else if(c.type==='ds18b20')text=d.lastTemperature.toFixed(2)+' °C · '+d.resolution+' bit'+(d.converting?' · BUSY':'');else if(c.type==='mhz19')text=d.ppm+' ppm · '+d.requests+' RX';else if(d.words!==undefined)text=d.words+' word · '+(d.on?'ON':'SHUTDOWN');}else if(['diode','zener'].includes(c.type)){const q=sim.dc.deviceResults.get(c.id);text=q?value(q.voltage,'V')+' · '+value(q.i*1000,'mA')+' · '+q.state+' · bounded DC':'';}else if(c.type==='l298n'){const n=sim.dc.netlist.net;text=[1,2,3,4].map(i=>'OUT'+i+' '+value(sim.dc.voltages.get(n(c.id+':OUT'+i)),'V')).join(' · ');if([1,2,3,4].some(i=>Math.abs(sim.dc.currents.get('$sensor:'+c.id+':OUT'+i)||0)>2))text+=' · >2 A / limit modeli yok';}else if(c.type==='loadcell'){const n=sim.dc.netlist.net,va=sim.dc.voltages.get(n(c.id+':A+')),vb=sim.dc.voltages.get(n(c.id+':A-'));text=Number.isFinite(va)&&Number.isFinite(vb)?((va-vb)*1000).toFixed(4)+' mV · dört direnç':'E+/E− besleme yok';}else if(c.type==='opamp')text=[1,2].map(i=>{const a=sim.dc.opampResults?.get(c.id+':'+i);return 'OUT'+i+' '+value(a?.voltage,'V')+' · '+(a?.state||'Hi-Z');}).join(' / ');else if(c.type==='tmp36')text=value(sim.dc.sensorResults?.get(c.id)?.output,'V');else if(c.type==='ldr')text=Math.round(10000*(100/(c.params.lux??100))**.7)+' Ω';$('expanded-values').textContent=text;}
if($('reactive-state')){const r=packet.dc?.reactive?.[c.id];$('reactive-state').textContent=r?value(r.stored,c.type==='capacitor'?'V':'A')+' · '+(r.energy*1000).toFixed(3)+' mJ':'DC / sıfır başlangıç';}}
export function busRows(packet){const rows=[];for(const t of packet.spi?.transactions||[])rows.push({cycle:t.cycle,bus:'SPI',device:'MODE '+t.mode,status:Math.round(t.frequency/1000)+' kHz',data:'TX '+hex(t.mosi)+' → RX '+hex(t.miso)});for(const t of packet.onewire?.events||[])rows.push({cycle:t.cycle,bus:'1-Wire',device:t.id,status:t.kind,data:t.kind==='RESET'?(t.width/16).toFixed(1)+' µs':String(t.bit)});for(const t of packet.uartDevices?.events||[])rows.push({cycle:t.cycle,bus:'UART',device:t.id,status:'9600 8N1',data:t.request.map(hex).join(' ')+' → '+t.response.map(hex).join(' ')});return rows;}
